<script setup>
import { onMounted, onUnmounted, ref } from 'vue'
import html2canvas from 'html2canvas'

const loading = ref(false)
const showTip = ref(false)
const tipText = ref('')

const handleKeyDown = (e) => {
  if (e.ctrlKey && e.altKey && e.key.toLowerCase() === 'd') {
    e.preventDefault()
    capturePage()
  }
}

const capturePage = async () => {
  loading.value = true
  showTip.value = true
  tipText.value = '截图中'
  
  try {
    const canvas = await html2canvas(document.documentElement, {
      useCORS: true,
      scale: window.devicePixelRatio,
      logging: false,
      allowTaint: false,
      ignoreElements: (element) => {
        return element.classList.contains('top-nav')
      }
    })

    const imgData = canvas.toDataURL('image/png')
    downloadImage(imgData)
    
    tipText.value = '截图完成'
    setTimeout(() => {
      showTip.value = false
    }, 1500)
  } catch (err) {
    tipText.value = '截图失败'
    setTimeout(() => {
      showTip.value = false
    }, 2000)
  } finally {
    loading.value = false
  }
}

const downloadImage = (dataUrl) => {
  const link = document.createElement('a')
  const now = new Date()
  const fileName = `${now.getFullYear()}${(now.getMonth() + 1).toString().padStart(2, '0')}${now.getDate().toString().padStart(2, '0')}_${now.getHours().toString().padStart(2, '0')}${now.getMinutes().toString().padStart(2, '0')}${now.getSeconds().toString().padStart(2, '0')}.png`
  
  link.href = dataUrl
  link.download = fileName
  link.click()
}

onMounted(() => {
  window.addEventListener('keydown', handleKeyDown)
})

onUnmounted(() => {
  window.removeEventListener('keydown', handleKeyDown)
})
</script>

<template>
  <div></div>

  <div v-if="loading" class="screenshot-loading">
    <div class="screenshot-loading-bar"></div>
  </div>

  <div v-if="showTip" class="screenshot-tip">
    {{ tipText }}
  </div>
</template>

<style scoped>
.screenshot-loading {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 0.194rem;
  background: #e5e7eb;
  z-index: 9999;
  user-select: none;
}
.screenshot-loading-bar {
  height: 100%;
  width: 100%;
  background: var(--color-theme);
  animation: progress 0.8s linear infinite;
  user-select: none;
}
.screenshot-tip {
  position: fixed;
  top: 0.323rem;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(0, 0, 0, 0.7);
  color: #fff;
  padding: 0.161rem 0.323rem;
  z-index: 9999;
  font-size: 0.2rem;
  user-select: none;
}

@keyframes progress {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}
</style>